-- G28: immutable benchmark versions, deterministic comparisons, rollout gate.
create table public.automation_benchmark_suites(id uuid primary key default gen_random_uuid(),suite_key text not null,version text not null,manifest jsonb not null,manifest_checksum text not null,locked_at timestamptz not null,created_at timestamptz not null default now(),unique(suite_key,version),unique(manifest_checksum));
create table public.automation_benchmark_cases(id uuid primary key default gen_random_uuid(),suite_id uuid not null references public.automation_benchmark_suites(id) on delete restrict,case_key text not null,category text not null,fixture_payload jsonb not null,expected_result jsonb not null,critical boolean not null,created_at timestamptz not null default now(),unique(suite_id,case_key));
create table public.automation_benchmark_runs(id uuid primary key default gen_random_uuid(),suite_id uuid not null references public.automation_benchmark_suites(id) on delete restrict,pipeline_version text not null,model_version text,prompt_version text,taxonomy_release_id uuid references public.taxonomy_releases(id) on delete restrict,lexical_release_id uuid references public.lexical_releases(id) on delete restrict,difficulty_version text,qa_versions jsonb not null,status text not null check(status in('running','passed','failed','cancelled')),started_at timestamptz not null default now(),completed_at timestamptz);
create table public.automation_benchmark_results(id uuid primary key default gen_random_uuid(),run_id uuid not null references public.automation_benchmark_runs(id) on delete cascade,case_id uuid not null references public.automation_benchmark_cases(id) on delete restrict,actual_result jsonb not null,matched_expected boolean not null,latency_ms integer not null check(latency_ms>=0),details jsonb not null,created_at timestamptz not null default now(),unique(run_id,case_id));
create table public.automation_release_reports(id uuid primary key default gen_random_uuid(),run_id uuid not null unique references public.automation_benchmark_runs(id) on delete restrict,baseline_run_id uuid references public.automation_benchmark_runs(id) on delete restrict,pass_rate numeric not null check(pass_rate between 0 and 1),critical_pass_rate numeric not null check(critical_pass_rate between 0 and 1),regressions jsonb not null,decision text not null check(decision in('allow','block')),report_payload jsonb not null,created_at timestamptz not null default now());
create or replace function public.prevent_benchmark_mutation()returns trigger language plpgsql as $$begin raise exception 'benchmark_version_is_immutable';end$$;create trigger immutable_benchmark_suite before update or delete on public.automation_benchmark_suites for each row execute function public.prevent_benchmark_mutation();create trigger immutable_benchmark_case before update or delete on public.automation_benchmark_cases for each row execute function public.prevent_benchmark_mutation();
alter table public.automation_benchmark_suites enable row level security;alter table public.automation_benchmark_cases enable row level security;alter table public.automation_benchmark_runs enable row level security;alter table public.automation_benchmark_results enable row level security;alter table public.automation_release_reports enable row level security;create policy benchmark_suites_staff_read on public.automation_benchmark_suites for select using(public.is_staff());create policy benchmark_cases_staff_read on public.automation_benchmark_cases for select using(public.is_staff());create policy benchmark_runs_staff_read on public.automation_benchmark_runs for select using(public.is_staff());create policy benchmark_results_staff_read on public.automation_benchmark_results for select using(public.is_staff());create policy release_reports_staff_read on public.automation_release_reports for select using(public.is_staff());grant select on public.automation_benchmark_suites,public.automation_benchmark_cases,public.automation_benchmark_runs,public.automation_benchmark_results,public.automation_release_reports to authenticated;
